import React, { useState, useEffect } from "react";
import { useLocation } from "react-router-dom";
import axios from "axios";
import "../components/css/login.css";

const Register = () => {
  const location = useLocation();
  const [firstname, setFirstname] = useState('');
  const [lastname, setLastname] = useState('');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [otp, setOtp] = useState('');
  const [showOtpPopup, setShowOtpPopup] = useState(false);

  useEffect(() => {
    const params = new URLSearchParams(location.search);
    const emailParam = params.get("email");
    if (emailParam) {
      setEmail(emailParam);
    }
  }, [location]);

  const handleSubmit = async (e) => {
    e.preventDefault();

    if (password !== confirmPassword) {
      alert("Passwords do not match!");
      return;
    }

    try {
      const response = await axios.post('http://localhost:5000/api/owners/register', {
        firstname,
        lastname,
        email,
        password,
      });

      alert(response.data.message);
      setShowOtpPopup(true);
    } catch (error) {
      console.error("Registration error:", error.response ? error.response.data.message : error.message);
      alert(error.response ? error.response.data.message : 'An error occurred. Please try again.');
    }
  };

  const handleVerifyOtp = async () => {
    try {
      const response = await axios.post('http://localhost:5000/api/owners/verify-otp', {
        email,
        otp,
      });
      
      alert(response.data.message);
      setShowOtpPopup(false);
      window.location.href = '/login';
    } catch (error) {
      console.error("OTP verification error:", error.response ? error.response.data.message : error.message);
      alert(error.response ? error.response.data.message : 'OTP verification failed.');
    }
  };

  return (
    <div className="center-container">
      <div className="container-box">
        <h1>Register</h1>
        <form onSubmit={handleSubmit}>
          <div className="input-group">
            <label htmlFor="firstname">First Name</label>
            <input type="text" id="firstname" value={firstname} onChange={(e) => setFirstname(e.target.value)} placeholder="Enter your first name" required />
          </div>
          <div className="input-group">
            <label htmlFor="lastname">Last Name</label>
            <input type="text" id="lastname" value={lastname} onChange={(e) => setLastname(e.target.value)} placeholder="Enter your last name" required />
          </div>
          <div className="input-group">
            <label htmlFor="email">Email</label>
            <input type="email" id="email" value={email} onChange={(e) => setEmail(e.target.value)} placeholder="Enter your email" required />
          </div>
          <div className="input-group">
            <label htmlFor="password">Password</label>
            <input type="password" id="password" value={password} onChange={(e) => setPassword(e.target.value)} placeholder="Enter your password" required />
          </div>
          <div className="input-group">
            <label htmlFor="confirmPassword">Confirm Password</label>
            <input type="password" id="confirmPassword" value={confirmPassword} onChange={(e) => setConfirmPassword(e.target.value)} placeholder="Confirm your password" required />
          </div>
          
          <button type="submit" className="login-button">Register</button>
        </form>

        {showOtpPopup && (
          <div className="otp-popup">
            <h2>Verify OTP</h2>
            <input type="text" value={otp} onChange={(e) => setOtp(e.target.value)} placeholder="Enter OTP" />
            <button onClick={handleVerifyOtp}>Verify OTP</button>
          </div>
        )}

        <div className="register-link">
          <p>Already have an account? <a href="login">Login</a></p>
        </div>
      </div>
    </div>
  );
};

export default Register;
